def are_anagrams(str1, str2):
    """
    Determines if str1 can be rearranged to form str2.
    Returns True if they are anagrams (i.e. rearrangements of each other), otherwise False.
    """
    return sorted(str1) == sorted(str2)

def are_anagrams(s1: str, s2: str) -> bool:
    """
    Determine if two strings are anagrams of each other.

    Parameters:
    s1 (str): First input string.
    s2 (str): Second input string.

    Returns:
    bool: True if both strings are anagrams, False otherwise.
    """
    if len(s1) != len(s2):
        return False

    # Frequency dictionary to count occurrences of each character
    char_count = {}

    for char in s1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in s2:
        if char in char_count:
            char_count[char] -= 1
            if char_count[char] == 0:
                del char_count[char]
        else:
            return False

    return len(char_count) == 0

def extended_anagram(s1: str, s2: str) -> bool:
    """
    Determines if two strings are anagrams of each other, considering all printable ASCII characters
    and making the comparison case-insensitive.
    """
    # Normalize strings to lower case to make the comparison case insensitive
    s1 = s1.lower()
    s2 = s2.lower()

    # If lengths differ, they cannot be anagrams
    if len(s1) != len(s2):
        return False

    # Use dictionaries to count frequencies of characters
    count1 = {}
    count2 = {}

    for char in s1:
        if char in count1:
            count1[char] += 1
        else:
            count1[char] = 1

    for char in s2:
        if char in count2:
            count2[char] += 1
        else:
            count2[char] = 1

    # Compare the two dictionaries
    return count1 == count2

def group_anagrams(words):
    """
    Groups a list of words into anagrams while maintaining the order of their first occurrence.

    :param words: List of strings where each string is a word.
    :return: List of lists, where each sublist contains words that are anagrams.
    """
    anagrams_dict = {}
    result = []

    for word in words:
        key = ''.join(sorted(word))
        if key not in anagrams_dict:
            anagrams_dict[key] = []
        anagrams_dict[key].append(word)

    for word in words:
        key = ''.join(sorted(word))
        if key in anagrams_dict:
            result.append(anagrams_dict.pop(key))

    return result

import heapq

def trap_rain_water(elevation_map):
    if not elevation_map or not elevation_map[0]:
        return 0

    m, n = len(elevation_map), len(elevation_map[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Add all the boundary cells to the heap
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (elevation_map[i][j], i, j))
                visited[i][j] = True

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    water_trapped = 0

    while heap:
        height, x, y = heapq.heappop(heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                water_trapped += max(0, height - elevation_map[nx][ny])
                heapq.heappush(heap, (max(height, elevation_map[nx][ny]), nx, ny))

    return water_trapped

def is_anagram(s, t):
    if len(s) != len(t):
        return False

    # Initialize a dictionary to count characters
    char_count = {}

    # Count each character in the first string
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Decrease count for each character found in the second string
    for char in t:
        if char not in char_count:
            return False
        char_count[char] -= 1
        if char_count[char] < 0:
            return False

    # Ensure all counts are zero
    return all(value == 0 for value in char_count.values())

