from collections import Counter

def min_deletions_to_make_anagrams(word1, word2):
    """
    Returns the minimum number of deletions required to make the two strings anagrams.
    """
    count1 = Counter(word1)
    count2 = Counter(word2)

    # Find the characters that need to be deleted
    deletions = 0
    for char in count1:
        if char in count2:
            deletions += abs(count1[char] - count2[char])
        else:
            deletions += count1[char]

    for char in count2:
        if char not in count1:
            deletions += count2[char]

    return deletions

from typing import List

def count_anagram_pairs(words: List[str]) -> int:
    if not isinstance(words, list) or not all(isinstance(word, str) for word in words):
        raise TypeError("The input must be a list of strings.")

    anagram_map = {}
    for word in words:
        if not word.isalpha() or not word.islower():
            raise ValueError("Each word must consist of lowercase alphabets only.")

        sorted_word = ''.join(sorted(word))
        if sorted_word in anagram_map:
            anagram_map[sorted_word] += 1
        else:
            anagram_map[sorted_word] = 1

    count = 0
    for value in anagram_map.values():
        if value > 1:
            count += value * (value - 1) // 2

    return count

def is_anagram_optimized(s: str, t: str) -> bool:
    """
    Determines if string t is an anagram of string s.
    """
    if len(s) != len(t):
        return False

    count = [0] * 26

    for char in s:
        count[ord(char) - ord('a')] += 1

    for char in t:
        count[ord(char) - ord('a')] -= 1
        if count[ord(char) - ord('a')] < 0:
            return False

    return True

