def is_anagram_of_substring(s1: str, s2: str) -> bool:
    from collections import Counter

    if len(s1) > len(s2):
        return False

    s1_counter = Counter(s1)
    window_counter = Counter(s2[:len(s1)])

    if s1_counter == window_counter:
        return True

    for i in range(len(s1), len(s2)):
        window_counter[s2[i]] += 1
        window_counter[s2[i - len(s1)]] -= 1

        if window_counter[s2[i - len(s1)]] == 0:
            del window_counter[s2[i - len(s1)]]

        if s1_counter == window_counter:
            return True

    return False

import heapq

def trapRainWater(matrix):
    if not matrix or not matrix[0]:
        return 0

    n, m = len(matrix), len(matrix[0])
    visited = [[False] * m for _ in range(n)]
    heap = []

    # Push all the border cells into the heap with their heights
    for i in range(n):
        for j in [0, m-1]:
            heapq.heappush(heap, (matrix[i][j], i, j))
            visited[i][j] = True
    for j in range(1, m-1):
        for i in [0, n-1]:
            heapq.heappush(heap, (matrix[i][j], i, j))
            visited[i][j] = True

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    water_trapped = 0

    while heap:
        height, x, y = heapq.heappop(heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                water_trapped += max(0, height - matrix[nx][ny])
                heapq.heappush(heap, (max(matrix[nx][ny], height), nx, ny))
                visited[nx][ny] = True

    return water_trapped

