def minCost ( n : int , m : int , mask : int , prev : int , col : int ) -> int :
    global dp
    if mask == ( ( 1 << n ) - 1 ) :
        return 0
    if dp [ mask ] [ prev ] [ col == 1 ] != 0 :
        return dp [ mask ] [ prev ] [ col == 1 ]
    ans = int ( 1e9 )
    for i in range ( n ) :
        for j in range ( 2 ) :
            if graph [ prev ] [ i ] [ j ] and not ( mask & ( 1 << i ) ) and ( j != col ) :
                z = graph [ prev ] [ i ] [ j ] + minCost ( n , m , mask | ( 1 << i ) , i , j )
                ans = min ( z , ans )
    dp [ mask ] [ prev ] [ col == 1 ] = ans
    return dp [ mask ] [ prev ] [ col == 1 ]
